package com.shiphappens.logistics.service;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.entity.Statuses.*; import com.shiphappens.logistics.exception.ApiException; import com.shiphappens.logistics.repository.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class LogisticsService {
 private final CustomerRepository customers; private final OrderRepository orders; private final ShipmentRepository shipments; private final DriverRepository drivers; private final VehicleRepository vehicles; private final WarehouseRepository warehouses; private final DeliveryAssignmentRepository assignments; private final TrackingEventRepository events; private final PackageRepository packages; private final ApplicationEventPublisher publisher;
 public LogisticsService(CustomerRepository customers,OrderRepository orders,ShipmentRepository shipments,DriverRepository drivers,VehicleRepository vehicles,WarehouseRepository warehouses,DeliveryAssignmentRepository assignments,TrackingEventRepository events,PackageRepository packages,ApplicationEventPublisher publisher){this.customers=customers;this.orders=orders;this.shipments=shipments;this.drivers=drivers;this.vehicles=vehicles;this.warehouses=warehouses;this.assignments=assignments;this.events=events;this.packages=packages;this.publisher=publisher;}
 @Transactional public Customer createCustomer(Requests.Customer request){if(customers.existsByCustomerCode(request.customerCode()))throw conflict("Customer code already exists"); Customer c=new Customer();c.setCustomerCode(request.customerCode());c.setName(request.name());c.setEmail(request.email());c.setPhone(request.phone());return customers.save(c);}
 public List<Customer> listCustomers(){return customers.findAll();}
 @Transactional public Shipment createOrder(Requests.CreateOrder request,String externalReference){Customer c=customers.findById(request.customerId()).orElseThrow(()->notFound("Customer"));if(c.getStatus()!=CustomerStatus.ACTIVE)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INACTIVE_CUSTOMER","Inactive customers cannot create orders"); LogisticsOrder order=new LogisticsOrder();order.setCustomer(c);order.setExternalReference(externalReference);order.setOrderNumber(code("ORD"));order.setPickupAddress(toAddress(request.pickup()));order.setDeliveryAddress(toAddress(request.delivery()));order=orders.save(order); for(Requests.Package requestPackage:request.packages())packages.save(toPackage(order,requestPackage)); Shipment shipment=new Shipment();shipment.setOrder(order);shipment.setShipmentNumber(code("SHP"));shipment.setTrackingNumber(code("TRK"));shipment=shipments.save(shipment); recordEvent(shipment,"SHIPMENT_CREATED","Shipment created",null);return shipment;}
 @Transactional public Shipment updateShipment(Long id,Requests.ShipmentStatus request){Shipment shipment=findShipment(id);ShipmentStatus current=shipment.getStatus();if(!allowed(current,request.status()))throw conflict("Cannot transition shipment from "+current+" to "+request.status());shipment.setStatus(request.status());recordEvent(shipment,"SHIPMENT_"+request.status(),request.description()==null?"Shipment status changed to "+request.status():request.description(),request.location());publisher.publishEvent(new ShipmentStatusChanged(shipment.getId(),request.status()));return shipment;}
 @Transactional public DeliveryAssignment assign(Requests.AssignDelivery request){Shipment shipment=findShipment(request.shipmentId());if(shipment.getStatus()!=ShipmentStatus.CREATED&&shipment.getStatus()!=ShipmentStatus.AT_WAREHOUSE)throw conflict("Shipment must be CREATED or AT_WAREHOUSE before assignment");if(assignments.existsByShipmentAndStatusIn(shipment,List.of(DeliveryStatus.ASSIGNED,DeliveryStatus.PICKED_UP,DeliveryStatus.OUT_FOR_DELIVERY)))throw conflict("Shipment already has an active delivery assignment");Driver driver=drivers.findById(request.driverId()).orElseThrow(()->notFound("Driver"));Vehicle vehicle=vehicles.findById(request.vehicleId()).orElseThrow(()->notFound("Vehicle"));if(driver.getStatus()!=DriverStatus.AVAILABLE)throw conflict("Driver is not available");if(vehicle.getStatus()!=VehicleStatus.AVAILABLE)throw conflict("Vehicle is not available");if(packages.totalWeight(shipment.getOrder()).compareTo(vehicle.getCapacityKg())>0)throw conflict("Vehicle capacity is insufficient for this shipment");driver.setStatus(DriverStatus.ASSIGNED);vehicle.setStatus(VehicleStatus.ASSIGNED);DeliveryAssignment assignment=new DeliveryAssignment();assignment.setShipment(shipment);assignment.setDriver(driver);assignment.setVehicle(vehicle);return assignments.save(assignment);}
 @Transactional public DeliveryAssignment updateDelivery(Long id,Requests.DeliveryStatus request){DeliveryAssignment assignment=assignments.findById(id).orElseThrow(()->notFound("Delivery assignment"));DeliveryStatus current=assignment.getStatus();if(!validDeliveryTransition(current,request.status()))throw conflict("Cannot transition delivery from "+current+" to "+request.status());Shipment shipment=assignment.getShipment();if(request.status()==DeliveryStatus.PICKED_UP)updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.PICKED_UP,null,"Driver confirmed pickup"));if(request.status()==DeliveryStatus.OUT_FOR_DELIVERY)updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.OUT_FOR_DELIVERY,null,"Driver is out for delivery"));if(request.status()==DeliveryStatus.DELIVERED)updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.DELIVERED,null,"Delivery completed"));if(request.status()==DeliveryStatus.FAILED)updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.FAILED,null,request.failureReason()==null?"Delivery failed":request.failureReason()));assignment.setStatus(request.status());if(request.status()==DeliveryStatus.PICKED_UP)assignment.setPickupAt(java.time.Instant.now());if(request.status()==DeliveryStatus.OUT_FOR_DELIVERY)assignment.setOutForDeliveryAt(java.time.Instant.now());if(request.status()==DeliveryStatus.DELIVERED){assignment.setDeliveredAt(java.time.Instant.now());assignment.getDriver().setStatus(DriverStatus.AVAILABLE);assignment.getVehicle().setStatus(VehicleStatus.AVAILABLE);}if(request.status()==DeliveryStatus.FAILED){assignment.setFailureReason(request.failureReason());assignment.getDriver().setStatus(DriverStatus.AVAILABLE);assignment.getVehicle().setStatus(VehicleStatus.AVAILABLE);}return assignment;}
 @Transactional public Warehouse createWarehouse(Requests.Warehouse request){Warehouse w=new Warehouse();w.setWarehouseCode(request.warehouseCode());w.setName(request.name());w.setAddress(request.address());w.setCity(request.city());w.setState(request.state());w.setCapacity(request.capacity());w.setStatus(request.status());return warehouses.save(w);} @Transactional public Driver createDriver(Requests.Driver request){Driver d=new Driver();d.setDriverCode(request.driverCode());d.setName(request.name());d.setPhone(request.phone());d.setLicenseNumber(request.licenseNumber());return drivers.save(d);} @Transactional public Vehicle createVehicle(Requests.Vehicle request){Vehicle v=new Vehicle();v.setVehicleNumber(request.vehicleNumber());v.setVehicleType(request.vehicleType());v.setCapacityKg(request.capacityKg());return vehicles.save(v);} public List<Warehouse> warehouses(){return warehouses.findAll();}
 public Shipment findShipment(Long id){return shipments.findById(id).orElseThrow(()->notFound("Shipment"));} public List<Shipment> listShipments(ShipmentStatus status){return status==null?shipments.findAll():shipments.findByStatus(status);} public List<TrackingEvent> tracking(Long id){return events.findByShipmentOrderByCreatedAtAsc(findShipment(id));} public long count(ShipmentStatus status){return shipments.countByStatus(status);} public List<Driver> drivers(){return drivers.findAll();} public List<Vehicle> vehicles(){return vehicles.findAll();} public Customer customerByCode(String code){return customers.findByCustomerCode(code).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"CUSTOMER_NOT_FOUND","No active customer exists for customerCode "+code));} public Optional<LogisticsOrder> orderByExternalReference(String reference){return orders.findByExternalReference(reference);}
 private Address toAddress(Requests.Address r){Address a=new Address();a.setAddressLine1(r.addressLine1());a.setAddressLine2(r.addressLine2());a.setCity(r.city());a.setState(r.state());a.setPostalCode(r.postalCode());a.setCountry(r.country());return a;} private PackageItem toPackage(LogisticsOrder order,Requests.Package r){PackageItem item=new PackageItem();item.setPackageCode(code("PKG"));item.setOrder(order);item.setDescription(r.description());item.setWeightKg(r.weightKg());item.setLengthCm(r.lengthCm());item.setWidthCm(r.widthCm());item.setHeightCm(r.heightCm());item.setDeclaredValue(r.declaredValue());return item;} private void recordEvent(Shipment s,String type,String description,String location){TrackingEvent e=new TrackingEvent();e.setShipment(s);e.setEventType(type);e.setStatus(s.getStatus().name());e.setDescription(description);e.setLocation(location);events.save(e);} private boolean allowed(ShipmentStatus from,ShipmentStatus to){return switch(from){case CREATED->to==ShipmentStatus.PICKED_UP||to==ShipmentStatus.CANCELLED;case PICKED_UP->to==ShipmentStatus.IN_TRANSIT||to==ShipmentStatus.FAILED;case IN_TRANSIT->to==ShipmentStatus.AT_WAREHOUSE||to==ShipmentStatus.FAILED;case AT_WAREHOUSE->to==ShipmentStatus.OUT_FOR_DELIVERY||to==ShipmentStatus.FAILED;case OUT_FOR_DELIVERY->to==ShipmentStatus.DELIVERED||to==ShipmentStatus.FAILED||to==ShipmentStatus.AT_WAREHOUSE;case FAILED->to==ShipmentStatus.OUT_FOR_DELIVERY;default->false;};} private boolean validDeliveryTransition(DeliveryStatus from,DeliveryStatus to){return switch(from){case ASSIGNED->to==DeliveryStatus.PICKED_UP||to==DeliveryStatus.CANCELLED;case PICKED_UP->to==DeliveryStatus.OUT_FOR_DELIVERY||to==DeliveryStatus.FAILED;case OUT_FOR_DELIVERY->to==DeliveryStatus.DELIVERED||to==DeliveryStatus.FAILED;default->false;};} private String code(String prefix){return prefix+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();} private ApiException notFound(String type){return new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND",type+" not found");} private ApiException conflict(String message){return new ApiException(HttpStatus.CONFLICT,"BUSINESS_RULE_VIOLATION",message);} }
